// NOVEL — not generated by CLI Printing Press. See
// .printing-press-patches/garmin-sql-escape-hatch.json.
//
// The MCP `sql` tool's per-value memory bound. bound.SQLScanState.Add marshals
// a row to JSON before comparing it to the byte budget, so without a cap one
// oversized cell is built whole in this process before any budget applies —
// measured at 1.32 GB RSS on the `garmin-pp-cli sql` verb before it carried
// the same cap. These cases pin the refusal, its wording, and the fact that
// the tool refuses at exactly the constant the CLI verb uses.
//
// This file is hand-owned. internal/mcp/tools_test.go is generated and a
// re-render overwrites it; these cases live here so a reprint cannot silently
// take the cap's only failing test with it.

package mcp

import (
	"context"
	"database/sql"
	"fmt"
	"strings"
	"testing"
	"time"

	mcplib "github.com/mark3labs/mcp-go/mcp"
	"github.com/mvanhorn/printing-press-library/library/health/garmin/internal/sqlguard"
)

// setupBigCellMCPStore is setupEmptyMCPStore plus the rows the cap cases need:
// five 1 MiB rows whose concatenation clears the cap, and one ~200 KB row that
// must stay readable because the cap refuses any read that merely TOUCHES a
// stored value over the limit, not just one that returns it.
func setupBigCellMCPStore(t *testing.T) string {
	t.Helper()
	setupEmptyMCPStore(t)
	path, err := mcpDBPath()
	if err != nil {
		t.Fatalf("mcpDBPath() error = %v", err)
	}
	db, err := sql.Open("sqlite", path+"?_pragma=busy_timeout(5000)")
	if err != nil {
		t.Fatalf("opening fixture writer: %v", err)
	}
	defer db.Close() //nolint:errcheck // fixture

	if _, err := db.Exec(
		`INSERT INTO resources (id, resource_type, data) VALUES ('2026-02-01','sleep_detail',?)`,
		`{"note":"`+strings.Repeat("a", 200*1024)+`"}`,
	); err != nil {
		t.Fatalf("seeding the 200 KB row: %v", err)
	}
	mib := strings.Repeat("b", 1<<20)
	for i := 0; i < 5; i++ {
		if _, err := db.Exec(
			`INSERT INTO resources (id, resource_type, data) VALUES (?, 'bulk', ?)`,
			fmt.Sprintf("row-%d", i), mib,
		); err != nil {
			t.Fatalf("seeding bulk row %d: %v", i, err)
		}
	}
	return path
}

// callMCPSQLWithin runs handleSQL off the test goroutine and fails rather than
// hanging. handleSQL holds one capped connection open while mcpStoreStatus
// reads on a second, so the read-only store's pool of two is load-bearing: a
// pool of one would block forever here instead of erroring, and a stuck suite
// names nothing.
func callMCPSQLWithin(t *testing.T, query string, budget time.Duration) *mcplib.CallToolResult {
	t.Helper()
	type outcome struct {
		result *mcplib.CallToolResult
		err    error
	}
	done := make(chan outcome, 1)
	go func() {
		result, err := handleSQL(context.Background(), mcplib.CallToolRequest{Params: mcplib.CallToolParams{
			Arguments: map[string]any{"query": query},
		}})
		done <- outcome{result: result, err: err}
	}()
	select {
	case got := <-done:
		if got.err != nil {
			t.Fatalf("handleSQL returned transport error: %v", got.err)
		}
		if got.result == nil {
			t.Fatal("handleSQL returned nil result")
		}
		return got.result
	case <-time.After(budget):
		t.Fatalf("handleSQL did not return within %s (a connection-pool starvation blocks rather than errors)", budget)
		return nil
	}
}

// assertMCPCellCapRefusal pins the wording: a refusal that does not name the
// cap and a narrower way to ask leaves the agent guessing why a valid SELECT
// failed. Same three needles the CLI verb's refusal carries.
func assertMCPCellCapRefusal(t *testing.T, result *mcplib.CallToolResult) {
	t.Helper()
	text := mcpTextContent(t, result)
	if !result.IsError {
		t.Fatalf("an oversized cell was accepted; envelope: %.300s", text)
	}
	for _, want := range []string{"4 MiB", "substr(", "json_extract("} {
		if !strings.Contains(text, want) {
			t.Fatalf("refusal does not mention %q: %s", want, text)
		}
	}
}

// TestMCPSQLRefusesAnOversizedComputedCell is the defect case: before the cap
// this query materialised the whole value in this process and answered 200 OK.
func TestMCPSQLRefusesAnOversizedComputedCell(t *testing.T) {
	setupEmptyMCPStore(t)

	t.Run("first-row", func(t *testing.T) {
		result := callMCPSQLWithin(t,
			fmt.Sprintf(`SELECT hex(zeroblob(%d)) AS v`, sqlguard.MaxCellBytes), 60*time.Second)
		assertMCPCellCapRefusal(t, result)
	})

	// The refusal has two possible sites — the query call and the scan loop —
	// and only one of them is reached when the very first row is the oversized
	// one. A query whose second row is the big one covers the other.
	t.Run("later-row", func(t *testing.T) {
		result := callMCPSQLWithin(t, fmt.Sprintf(
			`SELECT hex(zeroblob(CASE v WHEN 1 THEN 10 ELSE %d END)) AS v FROM (SELECT 1 AS v UNION ALL SELECT 2)`,
			sqlguard.MaxCellBytes), 60*time.Second)
		assertMCPCellCapRefusal(t, result)
	})
}

// TestMCPSQLRefusesAnOversizedGroupConcat is the same defect reached through
// stored rows rather than zeroblob: group_concat builds one value out of many
// modest ones.
func TestMCPSQLRefusesAnOversizedGroupConcat(t *testing.T) {
	setupBigCellMCPStore(t)
	result := callMCPSQLWithin(t,
		`SELECT group_concat(data) AS v FROM resources WHERE resource_type='bulk'`, 60*time.Second)
	assertMCPCellCapRefusal(t, result)
}

// TestMCPSQLUnderCapStoredValueStillReadsWithStoreStatus is the other half of
// the contract. The cap refuses any read that touches a stored value above it,
// so a cap set too low would make the archive's own rows unreadable; and the
// envelope still has to carry store_status, which mcpStoreStatus reads on a
// second connection while the capped one is still checked out.
func TestMCPSQLUnderCapStoredValueStillReadsWithStoreStatus(t *testing.T) {
	setupBigCellMCPStore(t)
	result := callMCPSQLWithin(t,
		`SELECT length(json_extract(data,'$.note')) AS n FROM resources WHERE resource_type='sleep_detail'`,
		60*time.Second)
	if result.IsError {
		t.Fatalf("a 200 KB stored value under the cap was refused: %s", mcpTextContent(t, result))
	}
	text, envelope := decodeMCPSQLEnvelope(t, result)
	if envelope.Count != 1 || len(envelope.Rows) != 1 {
		t.Fatalf("under-cap read returned %d rows: %s", envelope.Count, text)
	}
	got, ok := envelope.Rows[0]["n"].(float64)
	if !ok || int(got) != 200*1024 {
		t.Fatalf("length(json_extract(...)) = %#v, want %d", envelope.Rows[0]["n"], 200*1024)
	}
	if !strings.Contains(text, `"store_status": "ready"`) {
		t.Fatalf("envelope lost store_status while the capped connection was held: %s", text)
	}
}

// TestMCPSQLRefusesAtTheSharedBoundary is what keeps the two surfaces one
// contract: the tool refuses at exactly the constant the CLI verb uses, not at
// a cap of its own.
func TestMCPSQLRefusesAtTheSharedBoundary(t *testing.T) {
	setupEmptyMCPStore(t)

	result := callMCPSQLWithin(t,
		fmt.Sprintf(`SELECT length(zeroblob(%d)) AS n`, sqlguard.MaxCellBytes-16), 60*time.Second)
	if result.IsError {
		t.Fatalf("a cell just under the cap was refused: %s", mcpTextContent(t, result))
	}
	text, envelope := decodeMCPSQLEnvelope(t, result)
	got, ok := envelope.Rows[0]["n"].(float64)
	if !ok || int(got) != sqlguard.MaxCellBytes-16 {
		t.Fatalf("under-cap cell reported length %#v, want %d in %s", envelope.Rows[0]["n"], sqlguard.MaxCellBytes-16, text)
	}

	result = callMCPSQLWithin(t,
		fmt.Sprintf(`SELECT length(zeroblob(%d)) AS n`, sqlguard.MaxCellBytes+16), 60*time.Second)
	assertMCPCellCapRefusal(t, result)
}
